const {test}=require('node:test'),assert=require('node:assert/strict');
const {readState,writeState,key}=require('./automation-state'),{fakeState}=require('./automation-state.test-helper');
const id='a'.repeat(32);
test('evidence round trips without Work Item fields and unchanged writes are skipped',async()=>{const f=fakeState(),value={repository:'repo',pr:3};await writeState(f.notion,id,'development-Web',value);assert.deepEqual((await readState(f.notion,id,'development-Web')).value,value);await writeState(f.notion,id,'development-Web',value);assert.equal(f.writes.length,1);assert.equal(f.rows[0].properties.Target.rich_text[0].text.content,'automation')});
test('uncertain create recovers the exact existing state',async()=>{const f=fakeState(),notion=async(path,method,body)=>{const result=await f.notion(path,method,body);if(path==='/pages')throw Error('lost response');return result};await writeState(notion,id,'scope',{targets:['web'],restrictions:''});assert.equal(f.rows.length,1)});
test('duplicates, wrong identities and malformed payloads fail closed',async()=>{for(const change of [f=>f.rows.push(structuredClone(f.rows[0])),f=>f.rows[0].properties['Work Item'].relation[0].id='b'.repeat(32),f=>f.rows[0].properties['Automation Evidence'].rich_text[0].text.content='bad']){const f=fakeState();await writeState(f.notion,id,'scope',{targets:[],restrictions:''});change(f);await assert.rejects(readState(f.notion,id,'scope'))}assert.throws(()=>key('bad','scope'))});
test('older RC snapshots cannot overwrite a newer observation',async()=>{const f=fakeState();await writeState(f.notion,id,'remote-config',{checkedAt:'2026-09-15T12:00:00Z',flags:{a:true}});await writeState(f.notion,id,'remote-config',{checkedAt:'2026-09-15T11:00:00Z',flags:{a:false}});assert.equal(f.writes.length,1)});
